let wrapper = root_element;

frappe.db.get_list('Company Policy', {
    fields: ['name', 'policy_name', 'department', 'office_entity'],
    limit: 0 
}).then(records => {
    
    // We will now store the EXACT database string to use in our URL filters
    let pillarsData = {
        'Human Resources': {},
        'Finance': {},
        'Procurement': {},
        'Communications': {}
    };

    records.forEach(record => {
        let rawDept = record.department ? record.department.trim().toUpperCase() : '';
        let deptName = '';

        // Group them into our 4 visual boxes
        if (rawDept === 'HR' || rawDept.includes('HUMAN RESOURCE')) {
            deptName = 'Human Resources';
        } else if (rawDept.includes('FINANCE')) {
            deptName = 'Finance';
        } else if (rawDept.includes('PROCURE')) {
            deptName = 'Procurement';
        } else if (rawDept.includes('COMMUNICAT')) {
            deptName = 'Communications';
        }

        if (deptName) {
            let entity = record.office_entity ? record.office_entity.trim() : 'Global';
            // THE MAGIC TRICK: Save the exact department string from the database
            pillarsData[deptName][entity] = record.department;
        }
    });

    function getDisplayInfo(entityStr) {
        let name = entityStr;
        let tag = entityStr;
        let upper = entityStr.toUpperCase();

        if (upper.includes('SINGAPORE')) tag = 'SEA';
        else if (upper.includes('MENA')) tag = 'MENA';
        else if (upper.includes('UNITED STATES') || upper.includes('USA')) tag = 'USA';
        else if (upper.includes('AFFORDABLE QUALITY HEALTH')) tag = 'AQH';
        else if (upper.includes('QUALITY HEALTHCARE ACCESS') || upper === 'QHA') tag = 'QHA';
        else if (upper.includes('PDF') || upper.includes('MANUAL')) tag = 'PDF';
        else if (upper.includes('GLOBAL') || entityStr === 'Global') tag = 'Global';
        else if (entityStr.includes('-')) {
            tag = entityStr.split('-').pop().trim();
            name = entityStr.split('-').slice(0, -1).join('-').trim();
        }

        return { name, tag };
    }

    function getTagStyle(tag) {
        const t = tag.toUpperCase();
        if (t === 'PDF') return 'color: #ef4444; background: #fee2e2;'; 
        if (t === 'SEA') return 'color: #3b82f6; background: #dbeafe;'; 
        if (t === 'MENA') return 'color: #a855f7; background: #f3e8ff;'; 
        if (t === 'USA') return 'color: #f97316; background: #ffedd5;'; 
        if (t === 'AQH') return 'color: #22c55e; background: #dcfce7;'; 
        if (t === 'QHA') return 'color: #14b8a6; background: #ccfbf1;'; 
        return 'color: #64748b; background: #f1f5f9;'; 
    }

    let html = '<div style="display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px;">';

    const config = {
        'Human Resources': { icon: '👥', bg: '#f0fdf4' },
        'Finance': { icon: '💰', bg: '#fef3c7' },
        'Procurement': { icon: '📦', bg: '#eff6ff' },
        'Communications': { icon: '📢', bg: '#fce7f3' }
    };

    const order = ['Human Resources', 'Finance', 'Procurement', 'Communications'];

    order.forEach(pillar => {
        html += `
        <div style="background: #ffffff; border: 1px solid #e2e8f0; border-radius: 8px; padding: 20px;">
            <div style="display: flex; align-items: center; gap: 10px; margin-bottom: 15px; padding-bottom: 15px; border-bottom: 1px solid #f1f5f9;">
                <span style="font-size: 16px; background: ${config[pillar].bg}; padding: 6px 8px; border-radius: 6px;">${config[pillar].icon}</span>
                <h3 style="font-size: 15px; font-weight: 600; color: #0f172a; margin: 0; font-family: inherit;">${pillar}</h3>
            </div>
            <ul style="list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 8px;">`;

        // Get the list of unique companies for this pillar
        let unique_entities = Object.keys(pillarsData[pillar]);
        unique_entities.sort((a, b) => a.localeCompare(b));

        if (unique_entities.length === 0) {
            html += `<li style="font-size: 12px; color: #94a3b8;">No policies published yet.</li>`;
        } else {
            unique_entities.forEach(raw_entity => {
                let info = getDisplayInfo(raw_entity);
                let tagStyle = getTagStyle(info.tag);
                
                // Get the exact database spelling for the department
                let exactDbDept = pillarsData[pillar][raw_entity];
                
                // Construct the URL perfectly matching the database values
                let linkUrl = `/app/company-policy?department=${encodeURIComponent(exactDbDept)}`;
                
                if (raw_entity !== 'Global') {
                    linkUrl += `&office_entity=${encodeURIComponent(raw_entity)}`;
                } else {
                    linkUrl += `&office_entity=ACCESS+Health+International+Global`;
                }

                html += `
                <li>
                    <a href="${linkUrl}" style="display: flex; justify-content: space-between; align-items: center; padding: 10px 12px; background: #f8fafc; border-radius: 6px; color: #334155; text-decoration: none; font-size: 12px; font-weight: 500; font-family: inherit;">
                        <span>${info.name}</span>
                        <span style="font-size: 10px; font-weight: 600; padding: 2px 6px; border-radius: 4px; ${tagStyle}">${info.tag}</span>
                    </a>
                </li>`;
            });
        }
        html += `</ul></div>`;
    });

    html += `</div>`;
    
    let container = wrapper.querySelector('#access-policy-grid');
    if (container) {
        container.innerHTML = html;
    } else {
        wrapper.innerHTML = html;
    }
});
